package com.yeyamo_mobile.api.partner_service.infrastructure.storage;
import java.io.*;import java.nio.file.*;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.partner_service.application.port.DocumentStoragePort;
@Component public class FilesystemDocumentStorageAdapter implements DocumentStoragePort{private final Path root;public FilesystemDocumentStorageAdapter(@Value("${yeyamo.documents.storage-root:./data/partner-documents}")String root)throws IOException{this.root=Paths.get(root).toAbsolutePath().normalize();Files.createDirectories(this.root);}public String store(String owner,String filename,String type,InputStream content)throws IOException{String extension=type.equals("application/pdf")?".pdf":type.equals("image/png")?".png":".jpg";Path dir=root.resolve(owner).normalize();if(!dir.startsWith(root))throw new SecurityException("Invalid owner key");Files.createDirectories(dir);Path target=dir.resolve(UUID.randomUUID()+extension);Files.copy(content,target,StandardCopyOption.REPLACE_EXISTING);return root.relativize(target).toString().replace('\\','/');}public InputStream open(String key)throws IOException{return Files.newInputStream(resolve(key));}public void delete(String key)throws IOException{Files.deleteIfExists(resolve(key));}private Path resolve(String key){Path target=root.resolve(key).normalize();if(!target.startsWith(root))throw new SecurityException("Invalid storage key");return target;}}
